{"thought": "normalize_whitespace strips zero-width chars and collapses whitespace to single spaces, no leading/trailing. Now I'll implement wrap_text. The spec is clear: validate width>=1, clean text, split on spaces, greedily fill lines. If text empty after cleaning, return [].", "action": {"tool": "edit_file", "args": {"path": "src/textkit/wrap_text.py", "old": "    raise NotImplementedError", "new": "    if width < 1:
        raise ValueError("width must be >= 1")
    from textkit.normalize_whitespace import normalize_whitespace

    cleaned = normalize_whitespace(text)
    if not cleaned:
        return []

    words = cleaned.split(" ")
    lines: List[str] = []
    current: List[str] = []
    current_len = 0
    for word in words:
        if current:
            # adding word would need one extra space
            if current_len + 1 + len(word) <= width:
                current.append(word)
                current_len += 1 + len(word)
            else:
                lines.append(" ".join(current))
                current = [word]
                current_len = len(word)
        else:
            current = [word]
            current_len = len(word)
    if current:
        lines.append(" ".join(current))
    return lines"}}, "messages": []}

